"""
    Finds the sum of all multiples of 3 and 5 of an integer.
    :param n: an integer value.
    :return: the sum of all multiples of 3 and 5.
    """
def find(n: Any) -> object {
    return sum(
        x
        for x in range((n + 1))
        if (((x % 5) == 0) or ((x % 3) == 0))
    );
}

""" bottom up implementation of cut rod memoized algorithm """
def bottom_up_cut_rod(price: Any, length: Any) -> object {
    incomelst = [float("-Inf") for _ in range((length + 1))];
    incomelst[0] = 0;
    for j in range(1, (length + 1)) {
        income = float("-Inf");
        for i in range(j) {
            income = max(income, (price[i] + incomelst[(j - i - 1)]));
        }
        incomelst[j] = income;
    }
    return incomelst[length];
}

"""obtain the drop_indices given the keep_indices.

    Args:
        num_chunks (int): The total number of chunks
        keep_indices (List): The keep indices.

    Returns: List. The dropped indices (frozen chunks).

    """
def get_drop_indices(num_chunks: Any, keep_indices: Any) -> object {
    drop_indices = [];
    for i in range(num_chunks) {
        if (i not in keep_indices) {
            drop_indices.append(i);
        }
    }
    return drop_indices;
}
